import{_ as l,a0 as r,w as o,s as d,ao as t,I as p,x as a,a1 as e,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"初次登录 Linux 服务器马上要做的 9 件事 | LCTT x X-CMD","titleTemplate":false,"description":"初次登录 Linux 服务器马上要做的 9 件事 | LCTT (202012) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"初次登录 Linux 服务器马上要做的 9 件事 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"初次登录 Linux 服务器马上要做的 9 件事 | LCTT (202012) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202012/20201215 9 things to do in your first 10 minutes on a Linux server","title":"初次登录 Linux 服务器马上要做的 9 件事","tag":"202012","desc":""},"relativePath":"202012/20201215 9 things to do in your first 10 minutes on a Linux server.md","filePath":"[post].md"}'),h={name:"202012/20201215 9 things to do in your first 10 minutes on a Linux server.md"};function c(u,s,g,k,b,m){const n=r("Link");return o(),d("div",null,[s[18]||(s[18]=t(`<h1 id="初次登录-linux-服务器马上要做的-9-件事" tabindex="-1">初次登录 Linux 服务器马上要做的 9 件事 <a class="header-anchor" href="#初次登录-linux-服务器马上要做的-9-件事" aria-label="Permalink to “初次登录 Linux 服务器马上要做的 9 件事”">​</a></h1><blockquote><p>在将新配置的服务器投入工作之前，请确保你知道你正在使用什么。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202012/27/112042zuz1lpudkypeppeu.jpg" alt=""></p><p>当我在 Linux 上测试软件时（这是我工作中的一个常规部分），我需要使用多台运行 Linux 的不同架构的服务器。我整备机器，安装所需的软件包，运行我的测试，收集结果，并将机器返回到仓库中，以便其他人可以使用它进行测试。</p><p>由于我经常这样做（甚至一天多次），我初次登录 Linux 服务器的前 10 分钟内的工作已经成为每天的仪式。当我初次登录 Linux 服务器时，我会使用命令来收集我需要的信息来寻找某些东西。我将在本文中介绍我的过程，但请注意，在大多数情况下，我只给出命令名称，所以你需要确定这些命令的具体选项，以获得你需要的信息。阅读命令的手册页是一个很好的起点。</p><h3 id="_1、第一次接触" tabindex="-1">1、第一次接触 <a class="header-anchor" href="#_1、第一次接触" aria-label="Permalink to “1、第一次接触”">​</a></h3><p>当我登录到一台服务器时，我做的第一件事就是检查它是否拥有我将要运行的测试所需的操作系统、内核和硬件架构。我经常会检查一台服务器已经运行了多久。虽然这对测试系统来说并不重要，因为它会被多次重启，但我还是发现这些信息很有帮助。</p><p>使用下面的命令来获取这些信息。我主要使用 Red Hat Linux 进行测试，所以如果你使用其他 Linux 发行版，请在文件名中使用 <code>*-release</code> 而不是 <code>redhat-release</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cat /etc/redhat-release</span></span>
<span class="line"><span>uname -a</span></span>
<span class="line"><span>hostnamectl</span></span>
<span class="line"><span>uptime</span></span></code></pre></div><h3 id="_2、有人登录在上面吗" tabindex="-1">2、有人登录在上面吗？ <a class="header-anchor" href="#_2、有人登录在上面吗" aria-label="Permalink to “2、有人登录在上面吗？”">​</a></h3><p>一旦我知道这台机器符合我的测试需求，我需要确保没有其他人同时登录该系统运行他们自己的测试。虽然考虑到整备系统会帮我处理好这个问题，这种可能性很小，但偶尔检查一下还是有好处的 —— 尤其是当我第一次登录服务器的时候。我还会检查是否有其他用户（除了 root）可以访问系统。</p><p>使用下面的命令来查找这些信息。最后一条命令是查找 <code>/etc/passwd</code> 文件中具有 shell 访问权限的用户；它会跳过文件中没有 shell 访问权限或 shell 设置为 <code>nologin</code> 的其他服务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>who</span></span>
<span class="line"><span>who -Hu</span></span>
<span class="line"><span>grep sh$ /etc/passwd</span></span></code></pre></div><h3 id="_3、物理机还是虚拟机" tabindex="-1">3、物理机还是虚拟机 <a class="header-anchor" href="#_3、物理机还是虚拟机" aria-label="Permalink to “3、物理机还是虚拟机”">​</a></h3><p>现在我有了属于自己的机器，我需要确定它是一台物理机还是一台虚拟机（VM）。如果是我自己整备的这台机器，我可以确定这是我要求的东西。但是，如果你使用的是一台不是你自己整备的机器，你应该检查该机器是物理机还是虚拟机。</p><p>使用以下命令来识别这些信息。如果是物理系统，你会看到供应商的名称（如 HP、IBM 等）以及服务器的品牌和型号；而在虚拟机中，你应该看到 KVM、VirtualBox 等，这取决于创建虚拟机时使用了什么虚拟化软件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dmidecode -s system-manufacturer</span></span>
<span class="line"><span>dmidecode -s system-product-name</span></span>
<span class="line"><span>lshw -c system | grep product | head -1</span></span>
<span class="line"><span>cat /sys/class/dmi/id/product_name</span></span>
<span class="line"><span>cat /sys/class/dmi/id/sys_vendor</span></span></code></pre></div><h3 id="_4、硬件" tabindex="-1">4、硬件 <a class="header-anchor" href="#_4、硬件" aria-label="Permalink to “4、硬件”">​</a></h3><p>因为我经常测试连接到 Linux 机器的硬件，所以我通常使用物理服务器，而不是虚拟机。在物理机器上，我的下一步是确定服务器的硬件能力 —— 例如，运行的是什么类型的 CPU，它有多少个核心，启用了哪些标志，以及有多少内存可用于运行测试。如果我正在运行网络测试，我会检查连接到服务器的以太网或其他网络设备的类型和容量。</p><p>使用以下命令来显示连接到 Linux 服务器的硬件。其中一些命令在新的操作系统版本中可能会被废弃，但你仍然可以从 yum 存储库中安装它们或切换到它们的等效新命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lscpu or cat /proc/cpuinfo</span></span>
<span class="line"><span>lsmem or cat /proc/meminfo</span></span>
<span class="line"><span>ifconfig -a</span></span>
<span class="line"><span>ethtool &lt;devname&gt;</span></span>
<span class="line"><span>lshw</span></span>
<span class="line"><span>lspci</span></span>
<span class="line"><span>dmidecode</span></span></code></pre></div><h3 id="_5、已安装的软件" tabindex="-1">5、已安装的软件 <a class="header-anchor" href="#_5、已安装的软件" aria-label="Permalink to “5、已安装的软件”">​</a></h3><p>测试软件总是需要安装额外的依赖包、库等。然而，在安装任何东西之前，我都会检查已经安装了什么（包括是什么版本），以及配置了哪些存储库，这样我就知道软件来自哪里，并可以调试任何软件包安装问题。</p><p>使用下面的命令来确定安装了什么软件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rpm -qa</span></span>
<span class="line"><span>rpm -qa | grep &lt;pkgname&gt;</span></span>
<span class="line"><span>rpm -qi &lt;pkgname&gt;</span></span>
<span class="line"><span>yum repolist</span></span>
<span class="line"><span>yum repoinfo</span></span>
<span class="line"><span>yum install &lt;pkgname&gt;</span></span>
<span class="line"><span>ls -l /etc/yum.repos.d/</span></span></code></pre></div><h3 id="_6、运行的进程和服务" tabindex="-1">6、运行的进程和服务 <a class="header-anchor" href="#_6、运行的进程和服务" aria-label="Permalink to “6、运行的进程和服务”">​</a></h3><p>检查了安装的软件之后，自然就会检查系统上有哪些进程在运行。当在系统上运行性能测试时，这一点至关重要 —— 如果一个正在运行的进程、守护进程、测试软件等占用了大部分 CPU/RAM，那么在运行测试之前停止该进程是有意义的。这也可以检查测试所需的进程或守护进程是否已经启动并运行。例如，如果测试需要 <code>httpd</code> 运行，那么即使安装了软件包，启动守护进程的服务也可能没有运行。</p><p>使用以下命令来识别系统上正在运行的进程和已启用的服务：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pstree -pa 1</span></span>
<span class="line"><span>ps -ef</span></span>
<span class="line"><span>ps auxf</span></span>
<span class="line"><span>systemctl</span></span></code></pre></div><h3 id="_7、网络连接" tabindex="-1">7、网络连接 <a class="header-anchor" href="#_7、网络连接" aria-label="Permalink to “7、网络连接”">​</a></h3><p>如今的机器网络化程度很高，它们需要与网络上的其他机器或服务进行通信。我会识别服务器上哪些端口是开放的，是否有到测试机器的任何网络连接，是否启用了防火墙，如果启用了，是否屏蔽了任何端口，以及机器与哪些 DNS 服务器对话。</p><p>使用以下命令来识别网络服务相关信息。如果一个过时的命令不可用，请从 yum 存储库中安装它或使用等效的新命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>netstat -tulpn</span></span>
<span class="line"><span>netstat -anp</span></span>
<span class="line"><span>lsof -i</span></span>
<span class="line"><span>ss</span></span>
<span class="line"><span>iptables -L -n</span></span>
<span class="line"><span>cat /etc/resolv.conf</span></span></code></pre></div><h3 id="_8、内核" tabindex="-1">8、内核 <a class="header-anchor" href="#_8、内核" aria-label="Permalink to “8、内核”">​</a></h3>`,34)),p("p",null,[s[1]||(s[1]=a("在进行系统测试时，我发现了解内核相关的信息是很有帮助的，比如内核版本和加载了哪些内核模块。我还会列出任何",-1)),e(n,{href:"https://www.oreilly.com/library/view/red-hat-enterprise/9781785283550/ch10s05.html"},{default:i(()=>[...s[0]||(s[0]=[a("可调整的内核参数",-1)])]),_:1}),s[2]||(s[2]=a("以及它们的设置，并检查启动运行中的内核时使用的选项。",-1))]),s[19]||(s[19]=t(`<p>使用以下命令来识别这些信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>uname -r</span></span>
<span class="line"><span>cat /proc/cmdline</span></span>
<span class="line"><span>lsmod</span></span>
<span class="line"><span>modinfo &lt;module&gt;</span></span>
<span class="line"><span>sysctl -a</span></span>
<span class="line"><span>cat /boot/grub2/grub.cfg</span></span></code></pre></div><h3 id="_9、日志" tabindex="-1">9、日志 <a class="header-anchor" href="#_9、日志" aria-label="Permalink to “9、日志”">​</a></h3><p>现在，我已经对服务器有了很好的了解，包括安装了哪些软件，运行了哪些进程。还有一件事我无法逃避，那就是日志文件 —— 我需要知道在哪里可以查看不断更新的信息。</p><p>使用以下命令查看系统的日志：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>dmesg</span></span>
<span class="line"><span>tail -f /var/log/messages</span></span>
<span class="line"><span>journalctl</span></span></code></pre></div><h3 id="接下来的步骤" tabindex="-1">接下来的步骤 <a class="header-anchor" href="#接下来的步骤" aria-label="Permalink to “接下来的步骤”">​</a></h3><p>虽然命令和实用程序会发生变化，但它们所显示的基本信息大致不变。在你专注于掌握哪些命令之前，你需要对你要寻找的信息以及它属于什么类别有一个宏观的看法。</p><p>由于 Linux 将大部分信息保存在文件中，这些命令基本上是从文件中读取信息，并以一种易于理解的方式呈现出来。下一步的好做法是找出每个命令用来获取信息显示的文件。一个提示：寻找这些信息的方法是 <code>strace</code> 命令。</p><hr>`,10)),p("p",null,[s[4]||(s[4]=a("via: ",-1)),e(n,{href:"https://opensource.com/article/20/12/linux-server"},{default:i(()=>[...s[3]||(s[3]=[a("https://opensource.com/article/20/12/linux-server",-1)])]),_:1})]),p("p",null,[s[9]||(s[9]=a("作者：",-1)),e(n,{href:"https://opensource.com/users/gkamathe"},{default:i(()=>[...s[5]||(s[5]=[a("Gaurav Kamathe",-1)])]),_:1}),s[10]||(s[10]=a(" 选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[6]||(s[6]=[a("lujun9972",-1)])]),_:1}),s[11]||(s[11]=a(" 译者：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[7]||(s[7]=[a("wxy",-1)])]),_:1}),s[12]||(s[12]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[8]||(s[8]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[15]||(s[15]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[13]||(s[13]=[a("LCTT",-1)])]),_:1}),s[16]||(s[16]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[14]||(s[14]=[a("Linux中国",-1)])]),_:1}),s[17]||(s[17]=a(" 荣誉推出",-1))])])}const _=l(h,[["render",c]]);export{y as __pageData,_ as default};
